import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as i,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Multimodal (Bridge)","description":"Model-side multimodal mechanics bridge to Learn LLM; this repo keeps only the minimal application-side usage and one vision-capability case on the ZH side.","frontmatter":{"title":"Multimodal (Bridge)","description":"Model-side multimodal mechanics bridge to Learn LLM; this repo keeps only the minimal application-side usage and one vision-capability case on the ZH side.","domain":"tech","tags":["tech","multimodal","bridge","vision"],"navOrder":94,"topicId":"multimodal-bridge","layer":"9","status":"bridge","nodeType":"boundary","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/"}],"lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"tech/09-advanced/multimodal.md","filePath":"tech/09-advanced/multimodal.md","lastUpdated":1791166440000}'),n={name:"tech/09-advanced/multimodal.md"};function s(r,e,l,d,c,m){return i(),a("div",null,[...e[0]||(e[0]=[o('<blockquote><p><strong>Group</strong>: Advanced (bridge) | <strong>Previous group exit</strong>: run long-term with release gates and versioning | <strong>This page exit</strong>: know which engineering decision this topic affects, and when to go to Learn LLM</p></blockquote><h1 id="multimodal-bridge" tabindex="-1">Multimodal (Bridge) <a class="header-anchor" href="#multimodal-bridge" aria-label="Permalink to &quot;Multimodal (Bridge)&quot;">​</a></h1><blockquote><p><strong>Bridge page</strong>: multimodal tokenization (how images become tokens), cross-modal alignment mechanics, and vision-encoder derivations live in <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> (multimodal chapter). This repo keeps only the minimal usage an app engineer needs.</p></blockquote><h2 id="minimal-application-side-usage" tabindex="-1">Minimal application-side usage <a class="header-anchor" href="#minimal-application-side-usage" aria-label="Permalink to &quot;Minimal application-side usage&quot;">​</a></h2><p>Using multimodality well in an application (vision as the example) takes four things:</p><ol><li><strong>Message structure</strong>: images as content blocks (base64 / URL / Files API) alongside text — see the <a href="./../02-inference-interface/model-api.html">Model API contract</a>.</li><li><strong>Cost awareness</strong>: images convert to tokens by size and enter the context budget — large images are a real cost item.</li><li><strong>Placement technique</strong>: images perform better <strong>before</strong> the instruction/question; label multiple images with <code>Image 1:</code>, <code>Image 2:</code>.</li><li><strong>Capability boundaries</strong>: spatial reasoning, precise counting, and person identification are known weak spots; high-stakes flows require human review (see <a href="./../08-production/security.html">Security</a>).</li></ol><p>Productization note: when the same image repeats across turns, use the Files API <code>file_id</code> instead of re-sending base64 every turn.</p><h2 id="pages-in-this-section" tabindex="-1">Pages in this section <a class="header-anchor" href="#pages-in-this-section" aria-label="Permalink to &quot;Pages in this section&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Status</th><th>Content</th><th>Language side</th></tr></thead><tbody><tr><td><a href="/zh/tech/09-advanced/multimodal-vision-case.html">Claude Vision capabilities (zh)</a></td><td>case</td><td>Claude vision integration details: image sources, limits, token math, prompting tips (figures per the official docs)</td><td>ZH only</td></tr></tbody></table><h2 id="when-to-go-to-learn-llm" tabindex="-1">When to go to Learn LLM <a class="header-anchor" href="#when-to-go-to-learn-llm" aria-label="Permalink to &quot;When to go to Learn LLM&quot;">​</a></h2><ul><li>Want to know how images/audio are split into tokens and why size caps exist → Learn LLM, multimodal tokenization chapter</li><li>Want to understand vision-language alignment training and where multimodal capability comes from → Learn LLM, cross-modal mechanics chapter</li></ul><p>Vendor-side specifics (per-request image caps, file sizes, supported formats) follow the <a href="https://platform.claude.com/docs/en/build-with-claude/vision" target="_blank" rel="noreferrer">official docs</a> in real time; this repo does not maintain snapshot figures.</p>',12)])])}const b=t(n,[["render",s]]);export{f as __pageData,b as default};
